function rangeExtraction(list) {
  const result = [];
  for (let i = 0; i < list.length; i++) {
    let j = i;
    while (j + 1 < list.length && list[j + 1] === list[j] + 1) {
      j++;
    }
    if (j - i >= 2) {
      result.push(`${list[i]}-${list[j]}`);
      i = j;
    } else {
      result.push(list[i]);
    }
  }
  return result.join(',');
}

