function lruSimulation(capacity, ops) {
  const cache = new Map();
  const results = [];
  for (const op of ops) {
    const [type, keyStr, valStr] = op.split(' ');
    const key = Number(keyStr);
    if (type === 'GET') {
      if (!cache.has(key)) {
        results.push(-1);
      } else {
        const val = cache.get(key);
        cache.delete(key);
        cache.set(key, val);
        results.push(val);
      }
    } else if (type === 'PUT') {
      const val = Number(valStr);
      if (cache.has(key)) {
        cache.delete(key);
      } else if (cache.size >= capacity) {
        const firstKey = cache.keys().next().value;
        cache.delete(firstKey);
      }
      cache.set(key, val);
    }
  }
  return JSON.stringify(results);
}

