import json
from collections import OrderedDict
def lru_simulation(capacity, ops):
    cache = OrderedDict()
    res = []
    for op in ops:
        parts = op.split()
        t = parts[0]
        k = int(parts[1])
        if t == 'GET':
            if k not in cache:
                res.append(-1)
            else:
                cache.move_to_end(k)
                res.append(cache[k])
        elif t == 'PUT':
            v = int(parts[2])
            if k in cache:
                cache.move_to_end(k)
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            cache[k] = v
    return json.dumps(res)

