function formatDuration(seconds) {
  if (seconds === 0) return 'now';
  const units = [
    { name: 'year', secs: 365 * 24 * 3600 },
    { name: 'day', secs: 24 * 3600 },
    { name: 'hour', secs: 3600 },
    { name: 'minute', secs: 60 },
    { name: 'second', secs: 1 }
  ];
  const parts = [];
  for (let u of units) {
    if (seconds >= u.secs) {
      const val = Math.floor(seconds / u.secs);
      seconds %= u.secs;
      parts.push(`${val} ${u.name}${val > 1 ? 's' : ''}`);
    }
  }
  if (parts.length === 1) return parts[0];
  return parts.slice(0, -1).join(', ') + ' and ' + parts[parts.length - 1];
}

